def _anon():
    r = client.post("/api/v1/auth/anonymous")
    assert r.status_code == 200
    return r.json()


def _h(token):
    return {"Authorization": f"Bearer {token}"}


def test_link_apple_success(fresh_auth):
    a = _anon()
    r = client.post(
        "/api/v1/auth/link/apple",
        headers=_h(a["access_token"]),
        json={"provider_token": "mock:apple-sub-1"},
    )
    assert r.status_code == 200, r.text
    body = r.json()
    assert body["user"]["is_anonymous"] is False
    assert body["user"]["social_provider"] == "apple"
    assert body["user"]["social_subject"] == "apple-sub-1"
    assert body["user"]["id"] == a["user"]["id"]
    r2 = client.get("/api/v1/auth/me", headers=_h(body["access_token"]))
    assert r2.status_code == 200
    assert r2.json()["user"]["is_anonymous"] is False


